import{state}from"./state.js";import{adjustBalanceOnServer}from"./api.js";import{renderAll}from"./ui.js";import{showToast,showMobileEventNotification}from"./utils.js";import{applyServerFamilyData,flushPendingSave}from"./action-helpers.js";function getAwardDescription(t){const r=prompt("Описание:",t>0?"Бонус от родителей":"Списано родителями");return r?.trim()||(t>0?"Начисление":"Списание")}export function adminAwardCoins(){if(!state.isAdmin||!state.currentChildId)return showToast("Сначала выберите ребенка","error");const t=prompt("Количество монет (можно отрицательное):");if(null===t)return;const r=parseInt(t);if(!r)return showToast("Некорректная сумма","error");const e=getAwardDescription(r);e&&(async()=>{await flushPendingSave();const t=await adjustBalanceOnServer(state.currentChildId,r,e);t.success&&t.data?(applyServerFamilyData(t.data,{currentChildId:state.currentChildId}),renderAll(),showMobileEventNotification(`${r>0?"Начислено":"Списано"}: ${Math.abs(r)} мон.`,"success","Balance updated")):showToast(t.error||"Не удалось изменить баланс","error")})()}